(function(E){ const x = E["sales-m1"] = E["sales-m1"] || {units:{}}; x.units["sales-1-1"] = {"grammar":{"id":"c-sales-1-1-g","level":"B1","course":"sales","unit":"sales-1-1","title":"From feature to benefit: which means, so you can","titleTr":"Özellikten faydaya: which means, so you can","titleFa":"از ویژگی به فایده: which means و so you can","formsTable":{"headers":{"en":["Feature (a fact)","Benefit (so what?)"],"tr":["Özellik (bilgi)","Fayda (ne işe yarar?)"],"fa":["ویژگی (واقعیت)","فایده (به چه دردی می‌خورد؟)"]},"rows":[["The tiles are frost-proof,","which means they survive cold winters."],["The carton weighs only 5 kg,","so your team can stack it by hand."],["We pack the saffron in our own plant,","so we can print your label."],["The software saves every change,","which means nobody loses work."]]},"wrong":"The tiles are frost-proof, which mean they last outdoors.","right":"The tiles are frost-proof, which means they last outdoors.","blank":{"sentence":"The carton is vacuum-packed, which ___ the nuts stay fresh for a year.","word":"means","distractors":["mean","meaning"]},"wrong2":"It's light, so your team can to carry it easily.","right2":"It's light, so your team can carry it easily.","blank2":{"sentence":"The app works offline, so your drivers can ___ it anywhere.","word":"use","distractors":["to use","using"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Say the fact, then a comma and 'which means' + the result.","tr":"Bilgiyi söyle, sonra virgül ve 'which means' + sonuç.","fa":"اول واقعیت را بگو، بعد ویرگول بگذار و با which means نتیجه را بیاور.","ex":"The tiles are frost-proof, which means they last outdoors."},{"en":"'which' is the whole idea, so always 'means' with -s.","tr":"'which' fikrin tamamıdır; bu yüzden her zaman -s ile 'means'.","fa":"کلمه‌ی which به کل ایده برمی‌گردد؛ برای همین means همیشه با s می‌آید.","ex":"..., which means nobody loses work."},{"en":"Or: the fact, then 'so' + the customer + can + verb.","tr":"Ya da: bilgi, sonra 'so' + müşteri + can + fiil.","fa":"راه دوم این است: واقعیت را بگو، بعد so بیاور، بعد مشتری، بعد can و فعل.","ex":"It's light, so your team can carry it."},{"en":"After 'can', the bare verb. Never 'can to'.","tr":"'can'den sonra yalın fiil. Asla 'can to' değil.","fa":"بعد از can فعل ساده می‌آید، چون can هرگز با to نمی‌آید.","ex":"..., so they can use it every day."}],"test":{"en":"After every fact, ask 'So what?'. Your answer starts with 'which means' or 'so you can'.","tr":"Her bilgiden sonra 'Ne olmuş yani?' diye sor. Cevabın 'which means' ya da 'so you can' ile başlar.","fa":"بعد از هر واقعیت از خودت بپرس: «خب که چه؟». جوابت با which means یا so you can شروع می‌شود."},"contrast":{"en":"Turkish 'yani' and Persian «یعنی» don't change the verb, so learners write 'which mean' or 'can to carry'. English needs 'means' and a bare verb after 'can'.","tr":"Türkçede sonucu 'yani' ya da '-dığı için' ile bağlarız: 'Dona dayanıklı, yani dışarıda kullanılabilir.' İngilizcede 'which means' sabit bir kalıptır: which fikrin tamamını gösterir, bu yüzden 'means' -s alır. 'can'den sonra da 'to' gelmez.","fa":"در فارسی نتیجه را با «یعنی» یا «پس» وصل می‌کنیم: «در برابر یخ‌زدگی مقاوم است، یعنی بیرون هم دوام می‌آورد». در انگلیسی which means یک الگوی ثابت است. کلمه‌ی which به کل ایده‌ی قبلی اشاره دارد، پس means با s می‌آید. بعد از can هم to نمی‌آید."}},"errorWatch":[{"find":["which mean","which it means","which is mean"],"fix":{"en":"'which' stands for the whole idea: write 'which means'.","tr":"'which' fikrin tamamını gösterir: 'which means' yaz.","fa":"کلمه‌ی which به کل ایده اشاره دارد، پس بنویس which means."}},{"find":["can to"],"fix":{"en":"After 'can', no 'to': 'so they can use it'.","tr":"'can'den sonra 'to' yok: 'so they can use it'.","fa":"بعد از can، to نمی‌آید: so they can use it."}}]},"b2":{"id":"c-sales-1-1-b2","level":"B2","track":"B2","course":"sales","unit":"sales-1-1","title":"Start with the product: Made from..., Packed in...","titleTr":"Ürünle başla: Made from..., Packed in...","titleFa":"با محصول شروع کن: Made from...، Packed in...","formsTable":{"headers":{"en":["Participle clause","The product + verb"],"tr":["Fiilin üçüncü hâliyle yapı","Ürün + fiil"],"fa":["عبارت اسم مفعولی","محصول و فعل"]},"rows":[["Packed in Kerman,","our pistachios stay fresh for a year."],["Made from Turkish steel,","the valve survives high pressure."],["Designed for small shops,","the till app needs no training."]]},"wrong":"Made from Turkish steel, our customers love this valve.","right":"Made from Turkish steel, this valve lasts for years.","blank":{"sentence":"___ in Mersin, our olive oil reaches buyers in many countries.","word":"Bottled","distractors":["Bottling","Bottle"]},"wrong2":"Making from pure wool, the carpet is soft.","right2":"Made from pure wool, the carpet is soft.","blank2":{"sentence":"___ from pure wool, our carpets keep their colour for decades.","word":"Woven","distractors":["Weaving","Weave"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"Open with a past participle and a detail, then a comma.","tr":"Fiilin üçüncü hâli ve bir ayrıntıyla başla, sonra virgül.","fa":"جمله را با اسم مفعول و یک نکته‌ی جزئی شروع کن و بعد ویرگول بگذار.","ex":"Packed in Kerman, ..."},{"en":"The first noun after the comma is the product.","tr":"Virgülden sonraki ilk isim üründür.","fa":"اولین اسم بعد از ویرگول، خود محصول است.","ex":"..., our pistachios stay fresh for a year."},{"en":"Past participle, not -ing: the product does not do the action.","tr":"-ing değil, fiilin üçüncü hâli: eylemi ürün yapmıyor.","fa":"اسم مفعول بیاور، نه فعل با ing؛ چون محصول خودش کاری انجام نمی‌دهد.","ex":"Made from pure wool, not Making from"}],"test":{"en":"Ask: what is 'made' or 'woven'? It must be the first noun after the comma.","tr":"Sor: 'made' ya da 'woven' olan ne? Virgülden sonraki ilk isim o olmalı.","fa":"بپرس: چه چیزی made یا woven است؟ همان باید اولین اسم بعد از ویرگول باشد."},"contrast":{"en":"Turkish puts this information before the noun ('Kerman'da paketlenen fıstıklarımız') and Persian after it with «که». English can open the sentence with it, but then the first noun after the comma must be the product.","tr":"Türkçede bu bilgi ismin önüne gelir ('Kerman'da paketlenen fıstıklarımız'). İngilizcede cümle bununla açılabilir ama virgülden sonraki ilk isim ürün olmalıdır.","fa":"فارسی این اطلاعات را بعد از اسم با «که» می‌آورد («پسته‌هایی که در کرمان بسته‌بندی می‌شوند»). انگلیسی می‌تواند جمله را با آن شروع کند، ولی اولین اسم بعد از ویرگول باید خود محصول باشد."}},"errorWatch":[{"find":["making from","packing in kerman","weaving from","bottling in"],"fix":{"en":"Use the past participle: 'Made from...', 'Packed in...'.","tr":"Fiilin üçüncü hâlini kullan: 'Made from...', 'Packed in...'.","fa":"اسم مفعول به کار ببر: «Made from...»، «Packed in...»."}}],"useIn":{"en":"B2: start one line of your pitch with a participle clause (for example 'Packed in Kerman, our pistachios...').","tr":"B2: tanıtımının bir satırını bu yapıyla başlat (örneğin 'Packed in Kerman, our pistachios...').","fa":"مسیر B2: یک خط از معرفی‌ات را با ساختار اسم مفعول شروع کن (مثلاً «Packed in Kerman, our pistachios...»)."},"exitItem":{"from":"sales-1-1","kind":"blank","prompt":"___ for export, every carton carries a label in English and German.","options":["Packed","Packing","Packs"],"correct":0}},"vocab":{"id":"c-sales-1-1-v","level":"B1","category":"vocab","course":"sales","unit":"sales-1-1","goals":["career"],"title":{"en":"Products and benefits","tr":"Ürünler ve faydalar","fa":"محصول و فایده"},"cards":[{"word":"feature","sentence":"One feature of this mug is the double wall.","meaning":{"en":"A fact about what a product has or does.","tr":"özellik.","fa":"ویژگی"}},{"word":"benefit","sentence":"The benefit for your staff is less time at the counter.","meaning":{"en":"What a product does for the buyer.","tr":"fayda.","fa":"فایده؛ سودی که محصول برای مشتری دارد"}},{"word":"range","sentence":"Our new range has six sizes.","meaning":{"en":"A group of products from one company.","tr":"ürün yelpazesi, seri.","fa":"مجموعه‌ی محصولات"}},{"word":"brand","sentence":"We sell under our own brand in Turkey.","meaning":{"en":"A company's own name for its products.","tr":"marka.","fa":"برند؛ نام تجاری"}},{"word":"private label","sentence":"We also pack private label for supermarkets.","meaning":{"en":"Products a factory makes with another company's name on them.","tr":"başka bir firmanın markasıyla üretim (özel marka, fason).","fa":"تولید با برند مشتری (پرایوت لیبل)"}},{"word":"supplier","sentence":"A good supplier answers the phone when there is a problem.","meaning":{"en":"A company that sells goods to another company.","tr":"tedarikçi.","fa":"تأمین‌کننده"}},{"word":"shelf life","sentence":"The shelf life of these dates is 12 months.","meaning":{"en":"How long food can stay on sale.","tr":"raf ömrü","fa":"ماندگاری (مدت نگهداری)"}},{"word":"lightweight","sentence":"The new case is lightweight, so it costs less to ship.","meaning":{"en":"Not heavy.","tr":"hafif.","fa":"سبک"}},{"word":"durable","sentence":"Restaurants need durable plates that survive many washes.","meaning":{"en":"Lasting a long time, even with hard use.","tr":"dayanıklı.","fa":"بادوام"}},{"word":"pitch","sentence":"She practised her pitch three times before the call.","meaning":{"en":"A short talk that makes someone want to buy.","tr":"kısa satış konuşması.","fa":"معرفی کوتاه برای فروش"}}]},"judge":{"id":"c-sales-1-1-j","course":"sales","unit":"sales-1-1","type":"judge","title":{"en":"Feature, benefit, proof?","tr":"Özellik, fayda, kanıt?","fa":"ویژگی، فایده، مدرک؟"},"prompt":"Four opening lines to a buyer of ceramic tiles.","parts":["Benefit","Proof","Next step"],"instruction":{"en":"Tap what each line has. The line to send has all three.","tr":"Her satırda ne olduğuna dokun. Gönderilecek satırda üçü de var.","fa":"روی چیزهایی که هر خط دارد بزن. خطی که باید بفرستی هر سه را دارد."},"items":[{"by":"AI tool","answer":"We are thrilled to offer world-class tiles that will elevate your business to new heights.","present":[],"fix":{"en":"No fact, no proof and nothing to do next. Replace the big words with one number and one request.","tr":"Gerçek yok, kanıt yok, sonraki adım yok. Büyük sözlerin yerine bir rakam ve bir istek koy.","fa":"نه واقعیتی دارد، نه مدرکی، نه قدم بعدی. به‌جای کلمه‌های بزرگ یک عدد و یک درخواست بگذار."}},{"by":"New rep","answer":"Our tiles are 60 x 60 cm and 10 mm thick. Could I send you the catalogue?","present":["Next step"],"fix":{"en":"Facts, but no benefit. Ask 'so what?': 10 mm thick, which means fewer break on the way to your warehouse.","tr":"Gerçekler var ama fayda yok. 'Yani ne olmuş?' diye sor: 10 mm kalın, yani yolda daha azı kırılır.","fa":"واقعیت در آن هست، ولی فایده نه. بپرس «خب که چه؟»: ضخامت ۱۰ میلی‌متر یعنی در راه کمتر می‌شکند."}},{"by":"Sales rep","answer":"Our tiles are frost-proof, so you can sell them for outdoor use too. An independent lab tested them for 100 freeze cycles.","present":["Benefit","Proof"],"fix":{"en":"Strong, but it stops there. Add one small step: 'Could I send you four samples?'","tr":"Güçlü ama orada bitiyor. Küçük bir adım ekle: 'Could I send you four samples?'","fa":"قوی است، ولی همان‌جا تمام می‌شود. یک قدم کوچک اضافه کن: «Could I send you four samples?»"}},{"by":"Good model","answer":"Our tiles are frost-proof, which means you can sell them for outdoor use too. An independent lab tested them for 100 freeze cycles. Could I send you four samples?","present":["Benefit","Proof","Next step"],"fix":null}]},"speaking":{"rounds":[60,45,30],"id":"sales-1-1","course":"sales","unit":"sales-1-1","topic":{"en":"Your 30-second pitch","tr":"30 saniyelik tanıtımın","fa":"معرفی ۳۰ ثانیه‌ای تو"},"warmup":{"en":"Think of one product you could sell, and one buyer who needs it. No product yet? Use roasted pistachios for food shops.","tr":"Satabileceğin bir ürünü ve ona ihtiyacı olan bir alıcıyı düşün. Ürünün yoksa gıda mağazaları için kavrulmuş antep fıstığını kullan.","fa":"محصولی را که می‌توانی بفروشی و خریداری را که به آن نیاز دارد در نظر بگیر. محصولی نداری؟ پسته‌ی برشته برای فروشگاه‌های مواد غذایی را در نظر بگیر."},"questions":[{"en":"Say what you sell, where you are and who you sell to, in one sentence.","tr":"Ne sattığını, nerede olduğunu ve kime sattığını tek cümlede söyle.","fa":"در یک جمله بگو چه می‌فروشی، کجا هستی و به چه کسی می‌فروشی."},{"en":"Give two features as benefits for that buyer, and one proof.","tr":"O alıcı için faydaya çevrilmiş iki özellik ve bir kanıt söyle.","fa":"دو ویژگی را به شکل فایده برای آن خریدار بگو و یک مدرک هم بیاور."},{"en":"The buyer says: 'So why should I change supplier?' Answer, then ask for one small next step.","tr":"Alıcı diyor ki: 'So why should I change supplier?' Cevap ver, sonra küçük bir sonraki adım iste.","fa":"خریدار می‌گوید: «So why should I change supplier?» جواب بده، بعد یک قدم بعدی کوچک بخواه."}],"followups":[{"en":"Say the whole pitch again and time it. Is it under 30 seconds?","tr":"Tüm tanıtımı yeniden söyle ve süre tut. 30 saniyenin altında mı?","fa":"کل معرفی را دوباره بگو و زمانش را بگیر. کمتر از ۳۰ ثانیه شد؟"}],"expressions":[{"phrase":"We make ... for ...","meaning":{"en":"Says what you sell and who for.","tr":"Ne sattığını ve kimin için olduğunu söyler.","fa":"می‌گوید چه می‌فروشی و برای چه کسی."}},{"phrase":"..., which means you can ...","meaning":{"en":"Turns a fact into a benefit.","tr":"Bir gerçeği faydaya çevirir.","fa":"یک واقعیت را به فایده تبدیل می‌کند."}},{"phrase":"Could I send you ...?","meaning":{"en":"Asks for one small next step.","tr":"Küçük bir sonraki adım ister.","fa":"یک قدم بعدی کوچک می‌خواهد."}}],"model":"We pack pistachios in Kerman for food shops in Europe. Our cartons are vacuum-packed, which means they stay fresh for twelve months, so you throw away less stock. Each batch comes with a lab report, so your customs agent has the papers ready. If you already have a supplier, that's fine. Could I send you a one-kilo sample to compare?","selfCheck":[{"en":"I said what, where and for whom in one sentence.","tr":"Ne, nerede, kimin için olduğunu tek cümlede söyledim.","fa":"در یک جمله گفتم چه چیزی، کجا و برای چه کسی."},{"en":"I gave benefits, not only features.","tr":"Yalnızca özellik değil, fayda da söyledim.","fa":"فقط ویژگی نگفتم، فایده هم گفتم."},{"en":"I gave one proof the buyer can check.","tr":"Alıcının kontrol edebileceği bir kanıt verdim.","fa":"یک مدرک دادم که خریدار می‌تواند بررسی کند."},{"en":"I ended with one small next step.","tr":"Küçük bir sonraki adımla bitirdim.","fa":"با یک قدم بعدی کوچک تمام کردم."}]},"writing":{"id":"c-sales-1-1-w","course":"sales","unit":"sales-1-1","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your pitch email","tr":"Tanıtım e-postan","fa":"ایمیل معرفی تو"},"portfolio":"sales-final-1","prompt":{"en":"Write a pitch email (50-70 words) for your own product, or for this one: Turkish olive oil from Mersin in 5-litre tins; cold-pressed; acid under 0.5%, lab report for each batch; buyer: a small restaurant chain in Germany. Say who you are, give two features as benefits and one proof, and ask for one small next step.","tr":"Kendi ürünün için ya da şunun için bir tanıtım e-postası yaz (50-70 kelime): 5 litrelik tenekede Mersin'den Türk zeytinyağı; soğuk sıkım; asit oranı %0,5'in altında, her parti için laboratuvar raporu; alıcı: Almanya'da küçük bir restoran zinciri. Kim olduğunu söyle, faydaya çevrilmiş iki özellik ve bir kanıt ver, küçük bir sonraki adım iste.","fa":"برای محصول خودت، یا این محصول، یک ایمیل معرفی بنویس (۵۰ تا ۷۰ کلمه): روغن زیتون مرسین ترکیه در حلب ۵ لیتری؛ پرس سرد؛ اسیدیته زیر ۰٫۵ درصد، با گزارش آزمایشگاه برای هر محموله؛ خریدار: یک رستوران زنجیره‌ای کوچک در آلمان. بگو چه کسی هستی، دو ویژگی را به شکل فایده بگو، یک مدرک بده و یک قدم بعدی کوچک بخواه."},"model":"Dear Ms Weber,\n\nWe bottle olive oil in Mersin for restaurants in Europe. It comes in 5-litre tins, so your kitchen can store it easily. It is cold-pressed, which means it keeps its full taste. Its acid level is under 0.5%, and each batch has a lab report. Could I send you a sample tin next week?\n\nBest regards","frame":"Dear ___,\n\nWe ___ for ___. It ___, so ___. It ___, which means ___. ___ has a lab report. Could I send you ___?\n\nBest regards","words":[{"word":"which means"},{"word":"so"},{"word":"Could I"}],"minWords":50,"minSentences":4,"rubric":["Task done: who you are, two benefits, one proof, one next step","Organised: who first, then benefits, then the request","Language: which means and so + can, used correctly","Tone: plain and exact, no big empty words"],"rubricI18n":{"tr":["Görev: kim olduğun, iki fayda, bir kanıt, bir sonraki adım","Düzen: önce kim olduğun, sonra faydalar, sonra istek","Dil: which means ve so + can doğru kullanılmış","Üslup: sade ve net, içi boş büyük laflar yok"],"fa":["کامل بودن کار: چه کسی هستی، دو فایده، یک مدرک، یک قدم بعدی","نظم: اول معرفی خودت، بعد فایده‌ها، بعد درخواست","زبان: which means و so + can درست به کار رفته‌اند","لحن: ساده و دقیق، بدون کلمه‌های بزرگ و توخالی"]}},"exit":{"id":"c-sales-1-1-x","course":"sales","unit":"sales-1-1","type":"exit","items":[{"from":"sales-1-1","kind":"mcq","prompt":"A buyer asks: \"Why will my customers want this?\" Which answer gives a benefit?","options":["It weighs 220 grams and comes in a green box.","It's light, so they can take it on holiday.","It is our new product, and we launched it in May."],"correct":1,"point":1},{"from":"sales-1-1","kind":"blank","prompt":"The labels are in four languages, which ___ you can sell in four markets.","options":["mean","means","meaning"],"correct":1,"point":2},{"from":"sales-1-1","kind":"blank","prompt":"The spare parts ship in 48 hours, so your machines can ___ running.","options":["keep","to keep","keeping"],"correct":0,"point":2},{"from":"sales-1-1","kind":"mcq","prompt":"Which proof can a buyer really check?","options":["We are the best in the region.","Our customers are always happy.","Each batch comes with a lab report."],"correct":2,"point":1},{"from":"sales-1-1","kind":"mcq","prompt":"How should a 30-second pitch end?","options":["With one small next step","With the full price list","With the history of the company"],"correct":0,"point":1},{"from":"sales-1-1","kind":"mcq","prompt":"Who should a 30-second pitch speak to?","options":["One buyer with one problem","Every buyer in your whole market","Anyone who visits your website"],"correct":0,"point":1}]},"explain":{"id":"c-sales-1-1-e","course":"sales","unit":"sales-1-1","type":"explain","level":"B1","title":{"en":"Your product in 30 seconds","tr":"30 saniyede ürünün","fa":"محصولت در ۳۰ ثانیه"},"objective":{"en":"After this lesson, you can pitch a product in 30 seconds by turning its features into benefits for one buyer.","tr":"Bu dersin sonunda bir ürünü, özelliklerini tek bir alıcı için faydaya çevirerek 30 saniyede tanıtabileceksin.","fa":"بعد از این درس می‌توانی یک محصول را در ۳۰ ثانیه معرفی کنی و ویژگی‌هایش را برای یک خریدار به فایده تبدیل کنی."},"hook":{"en":"A pitch tells one buyer what your product does for them, not how good your company is. Buyers ignore claims any seller can make, but they listen to their own problem.","tr":"Tanıtım, tek bir alıcıya ürününün ona ne kazandırdığını söyler; şirketinin ne kadar iyi olduğunu değil. Alıcılar her satıcının söyleyebileceği iddiaları dikkate almaz, ama kendi sorunlarını dinler.","fa":"معرفی به یک خریدار می‌گوید محصولت برای او چه فایده‌ای دارد، نه اینکه شرکتت چقدر خوب است. خریدار به ادعاهایی که هر فروشنده‌ای می‌تواند بکند توجه نمی‌کند، اما به مشکل خودش گوش می‌دهد."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Build the pitch in four moves","tr":"Tanıtımı dört adımda kur","fa":"معرفی را در چهار قدم بساز"},"steps":[{"en":"Pick one buyer and one problem. A pitch for everyone interests nobody.","tr":"Tek bir alıcı ve tek bir sorun seç. Herkese yapılan tanıtım kimsenin ilgisini çekmez.","fa":"یک خریدار و یک مشکل را انتخاب کن. معرفی‌ای که برای همه باشد توجه هیچ‌کس را جلب نمی‌کند.","ex":"Buyer: a food shop that throws away stale stock."},{"en":"Turn each feature into a benefit. Ask: so what? Buyers pay for results, not facts.","tr":"Her özelliği faydaya çevir. Sor: yani ne olmuş? Alıcılar bilgiye değil, sonuca para öder.","fa":"هر ویژگی را به فایده تبدیل کن. بپرس: خب که چه؟ خریدار برای نتیجه پول می‌دهد، نه برای یک واقعیت.","ex":"Vacuum-packed, so you lose less stock."},{"en":"Add one proof the buyer can check, such as a number or a test. Strangers need evidence.","tr":"Alıcının kontrol edebileceği bir kanıt ekle: rakam ya da test gibi. Seni tanımayan biri kanıt ister.","fa":"مدرکی اضافه کن که خریدار بتواند بررسی کند، مثل عدد یا آزمایش. کسی که تو را نمی‌شناسد مدرک می‌خواهد.","ex":"Shelf life: 12 months. Lab report for each batch."},{"en":"End with one small next step. A small request is easy to accept.","tr":"Küçük bir sonraki adımla bitir. Küçük bir isteği kabul etmek kolaydır.","fa":"با یک قدم بعدی کوچک تمام کن. قبول کردن درخواست کوچک آسان است.","ex":"Could I send you a 1 kg sample?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"From feature to benefit: which means, so you can","tr":"Özellikten faydaya: which means, so you can","fa":"از ویژگی به فایده: which means و so you can"},"steps":[{"en":"Say the fact, then a comma and 'which means' + the result.","tr":"Bilgiyi söyle, sonra virgül ve 'which means' + sonuç.","fa":"اول واقعیت را بگو، بعد ویرگول بگذار و با which means نتیجه را بیاور.","ex":"The tiles are frost-proof, which means they last outdoors."},{"en":"'which' is the whole idea, so always 'means' with -s.","tr":"'which' fikrin tamamıdır; bu yüzden her zaman -s ile 'means'.","fa":"کلمه‌ی which به کل ایده برمی‌گردد؛ برای همین means همیشه با s می‌آید.","ex":"..., which means nobody loses work."},{"en":"Or: the fact, then 'so' + the customer + can + verb.","tr":"Ya da: bilgi, sonra 'so' + müşteri + can + fiil.","fa":"راه دوم این است: واقعیت را بگو، بعد so بیاور، بعد مشتری، بعد can و فعل.","ex":"It's light, so your team can carry it."},{"en":"After 'can', the bare verb. Never 'can to'.","tr":"'can'den sonra yalın fiil. Asla 'can to' değil.","fa":"بعد از can فعل ساده می‌آید، چون can هرگز با to نمی‌آید.","ex":"..., so they can use it every day."}],"table":{"headers":{"en":["Feature (a fact)","Benefit (so what?)"],"tr":["Özellik (bilgi)","Fayda (ne işe yarar?)"],"fa":["ویژگی (واقعیت)","فایده (به چه دردی می‌خورد؟)"]},"rows":[["The tiles are frost-proof,","which means they survive cold winters."],["The carton weighs only 5 kg,","so your team can stack it by hand."],["We pack the saffron in our own plant,","so we can print your label."],["The software saves every change,","which means nobody loses work."]]},"tip":{"en":"Turkish 'yani' and Persian «یعنی» don't change the verb, so learners write 'which mean' or 'can to carry'. English needs 'means' and a bare verb after 'can'.","tr":"Türkçede sonucu 'yani' ya da '-dığı için' ile bağlarız: 'Dona dayanıklı, yani dışarıda kullanılabilir.' İngilizcede 'which means' sabit bir kalıptır: which fikrin tamamını gösterir, bu yüzden 'means' -s alır. 'can'den sonra da 'to' gelmez.","fa":"در فارسی نتیجه را با «یعنی» یا «پس» وصل می‌کنیم: «در برابر یخ‌زدگی مقاوم است، یعنی بیرون هم دوام می‌آورد». در انگلیسی which means یک الگوی ثابت است. کلمه‌ی which به کل ایده‌ی قبلی اشاره دارد، پس means با s می‌آید. بعد از can هم to نمی‌آید."},"wrong":"It has a 48-hour battery, it means you charge it less.","right":"It has a 48-hour battery, which means you charge it less."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Selling across borders","tr":"Sınır ötesine satış","fa":"فروش به خریدار خارجی"},"body":{"en":"A foreign buyer doesn't know you. Say your country and what you make in the first sentence. Time your pitch: 30 seconds is about 70 words. Prepare one version for each type of buyer.","tr":"Yabancı alıcı seni tanımaz. İlk cümlede ülkeni ve ne ürettiğini söyle. Tanıtımına süre tut: 30 saniye yaklaşık 70 kelimedir. Her alıcı türü için bir versiyon hazırla.","fa":"خریدار خارجی تو را نمی‌شناسد. در جمله‌ی اول بگو از کدام کشوری و چه چیزی تولید می‌کنی. زمان معرفی‌ات را بگیر: ۳۰ ثانیه حدود ۷۰ کلمه است. برای هر نوع خریدار یک نسخه آماده کن."},"phrases":[{"phrase":"We make ... for ...","meaning":{"en":"Says what you sell and who for.","tr":"Ne sattığını ve kimin için olduğunu söyler.","fa":"می‌گوید چه می‌فروشی و برای چه کسی."}},{"phrase":"..., which means you can ...","meaning":{"en":"Turns a fact into a benefit.","tr":"Bir gerçeği faydaya çevirir.","fa":"یک واقعیت را به فایده تبدیل می‌کند."}},{"phrase":"Could I send you ...?","meaning":{"en":"Asks for one small next step.","tr":"Küçük bir sonraki adım ister.","fa":"یک قدم بعدی کوچک می‌خواهد."}},{"phrase":"benefit","meaning":{"en":"What a product does for the buyer.","tr":"fayda.","fa":"فایده؛ سودی که محصول برای مشتری دارد"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From a company speech to a pitch","tr":"Şirket konuşmasından gerçek tanıtıma","fa":"از سخنرانی شرکتی تا یک معرفی واقعی"},"item":"We are a leading company with high-quality products and many years of experience. Your facts: you pack pistachios in Kerman for food shops in Europe; the cartons stay fresh for 12 months.","answer":"We pack pistachios in Kerman for food shops in Europe. Our cartons stay fresh for 12 months, so you throw away less stock. Could I send you a sample?","walk":[{"en":"Cut what any seller could say: leading, high quality.","tr":"Her satıcının söyleyebileceğini çıkar: leading, high quality.","fa":"کلمه‌های leading و high quality را حذف کن، چون هر فروشنده‌ای می‌تواند آن‌ها را بگوید."},{"en":"Say what, where and for whom. Then one benefit with a number.","tr":"Ne, nerede, kimin için söyle. Sonra rakamlı bir fayda ver.","fa":"بگو چه چیزی را، کجا و برای چه کسی می‌فروشی. بعد یک فایده با عدد بیاور."},{"en":"Finish with a request that is easy to accept.","tr":"Kabul etmesi kolay bir istekle bitir.","fa":"با درخواستی تمام کن که قبول کردنش آسان باشد."}]},"quick":{"prompt":"A feature is a fact. A benefit answers the buyer's question: ___","options":["So what?","Who are you?","How old is it?"],"correct":0,"why":{"en":"So what?: a benefit says what the fact does for this buyer.","tr":"So what?: fayda, o gerçeğin bu alıcıya ne kazandırdığını söyler.","fa":"فایده جواب سؤال so what? است: می‌گوید این واقعیت برای همین خریدار چه سودی دارد."}},"remember":{"en":"After every fact, ask: so what for this buyer? You can now say in 30 seconds who you help, how, and what the next step is.","tr":"Her bilgiden sonra sor: bu alıcı için yani ne olmuş? Artık 30 saniyede kime, nasıl yardım ettiğini ve sonraki adımı söyleyebilirsin.","fa":"بعد از هر واقعیت بپرس: خب، این برای این خریدار چه فایده‌ای دارد؟ حالا می‌توانی در ۳۰ ثانیه بگویی به چه کسی و چطور کمک می‌کنی و قدم بعدی چیست."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Start with the product: Made from..., Packed in...","tr":"Ürünle başla: Made from..., Packed in...","fa":"با محصول شروع کن: Made from...، Packed in..."},"steps":[{"en":"Open with a past participle and a detail, then a comma.","tr":"Fiilin üçüncü hâli ve bir ayrıntıyla başla, sonra virgül.","fa":"جمله را با اسم مفعول و یک نکته‌ی جزئی شروع کن و بعد ویرگول بگذار.","ex":"Packed in Kerman, ..."},{"en":"The first noun after the comma is the product.","tr":"Virgülden sonraki ilk isim üründür.","fa":"اولین اسم بعد از ویرگول، خود محصول است.","ex":"..., our pistachios stay fresh for a year."},{"en":"Past participle, not -ing: the product does not do the action.","tr":"-ing değil, fiilin üçüncü hâli: eylemi ürün yapmıyor.","fa":"اسم مفعول بیاور، نه فعل با ing؛ چون محصول خودش کاری انجام نمی‌دهد.","ex":"Made from pure wool, not Making from"}],"table":{"headers":{"en":["Participle clause","The product + verb"],"tr":["Fiilin üçüncü hâliyle yapı","Ürün + fiil"],"fa":["عبارت اسم مفعولی","محصول و فعل"]},"rows":[["Packed in Kerman,","our pistachios stay fresh for a year."],["Made from Turkish steel,","the valve survives high pressure."],["Designed for small shops,","the till app needs no training."]]},"body":{"en":"B2: start one line of your pitch with a participle clause (for example 'Packed in Kerman, our pistachios...').","tr":"B2: tanıtımının bir satırını bu yapıyla başlat (örneğin 'Packed in Kerman, our pistachios...').","fa":"مسیر B2: یک خط از معرفی‌ات را با ساختار اسم مفعول شروع کن (مثلاً «Packed in Kerman, our pistachios...»)."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
